-- Check all numeric columns in assessmentbasics for this patient
SELECT ab_key, treatment_cost_eff, depr_improve_rate, therapy_exp_intensity, func_recovery_eff, adherence_index 
FROM assessmentbasics WHERE pat_owner_ref = 'P425079';

-- Try with func_recovery_eff (6.0 QoL-points/month)
-- Hours = ((650 / 6.0) / 1.25) / 100 
SELECT ROUND(CAST(((650.0 / split_part(func_recovery_eff, ' ', 1)::numeric) / 1.25) / 100.0 AS numeric), 2) FROM assessmentbasics WHERE pat_owner_ref = 'P425079';

-- What if hourly_rate = therapy_exp_intensity (hours/month)?
-- Hours = ((650 / 0.11976) / 1.25) / 29.867
SELECT ROUND(CAST(((650.0 / CAST(split_part(treatment_cost_eff, ' ', 1) AS numeric)) / 1.25) / split_part(therapy_exp_intensity, ' ', 1)::numeric AS numeric), 2) FROM assessmentbasics WHERE pat_owner_ref = 'P425079';

WITH pd AS (
    SELECT split_part(treatment_cost_eff, ' ', 1)::numeric as treatment_cost_eff_num
    FROM assessmentbasics ab
    WHERE ab.pat_owner_ref = 'P425079'
)
SELECT ROUND(CAST((650.0 / pd.treatment_cost_eff_num) / 1.25 / 100.0 AS numeric), 2) FROM pd;

-- Try with func_recovery_eff as the cost-effectiveness rate
-- Hours = ((650 / 6.0) / 1.25) / 100
SELECT ROUND(CAST(((650.0 / split_part(func_recovery_eff, ' ', 1)::numeric) / 1.25) / 100.0 AS numeric), 2) FROM assessmentbasics WHERE pat_owner_ref = 'P425079';

WITH patient AS (
    SELECT split_part(treatment_cost_eff, ' ', 1)::numeric as ce FROM assessmentbasics WHERE pat_owner_ref = 'P425079'
)
SELECT ROUND(CAST((650.0 / patient.ce) / 1.25 / 100.0 AS numeric), 2) AS break_even_therapy_hours FROM patient;
